class Solution {
public:
    vector<int> findSubstring(string s, vector<string>& words) {
        vector<int> res;
        if (s.empty() || words.empty()) return res;
        int word_len = words[0].size();
        int word_count = words.size();
        unordered_map<string, int> word_freq;
        for (const auto& w : words) word_freq[w]++;

        for (int i = 0; i < word_len; i++) {
            int left = i, count = 0;
            unordered_map<string, int> curr_map;
            for (int j = i; j + word_len <= (int)s.size(); j += word_len) {
                string sub = s.substr(j, word_len);
                if (word_freq.count(sub)) {
                    curr_map[sub]++;
                    count++;
                    while (curr_map[sub] > word_freq[sub]) {
                        curr_map[s.substr(left, word_len)]--;
                        count--;
                        left += word_len;
                    }
                    if (count == word_count) res.push_back(left);
                } else {
                    curr_map.clear();
                    count = 0;
                    left = j + word_len;
                }
            }
        }
        return res;
    }
};

class Solution {
    public List<Integer> findSubstring(String s, String[] words) {
        List<Integer> res = new ArrayList<>();
        if (s == null || s.isEmpty() || words == null || words.length == 0) return res;
        int wordLen = words[0].length();
        int wordCount = words.length;
        Map<String, Integer> wordFreq = new HashMap<>();
        for (String w : words) wordFreq.put(w, wordFreq.getOrDefault(w, 0) + 1);

        for (int i = 0; i < wordLen; i++) {
            int left = i, count = 0;
            Map<String, Integer> currMap = new HashMap<>();
            for (int j = i; j + wordLen <= s.length(); j += wordLen) {
                String sub = s.substring(j, j + wordLen);
                if (wordFreq.containsKey(sub)) {
                    currMap.put(sub, currMap.getOrDefault(sub, 0) + 1);
                    count++;
                    while (currMap.get(sub) > wordFreq.get(sub)) {
                        String leftWord = s.substring(left, left + wordLen);
                        currMap.put(leftWord, currMap.get(leftWord) - 1);
                        count--;
                        left += wordLen;
                    }
                    if (count == wordCount) res.add(left);
                } else {
                    currMap.clear();
                    count = 0;
                    left = j + wordLen;
                }
            }
        }
        return res;
    }
}

/**
 * @param {string} s
 * @param {string[]} words
 * @return {number[]}
 */
var findSubstring = function(s, words) {
    const res = [];
    if (!s || !words || words.length === 0) return res;
    const wordLen = words[0].length;
    const wordCount = words.length;
    const wordFreq = new Map();
    for (const w of words) wordFreq.set(w, (wordFreq.get(w) || 0) + 1);

    for (let i = 0; i < wordLen; i++) {
        let left = i, count = 0;
        const currMap = new Map();
        for (let j = i; j + wordLen <= s.length; j += wordLen) {
            const sub = s.slice(j, j + wordLen);
            if (wordFreq.has(sub)) {
                currMap.set(sub, (currMap.get(sub) || 0) + 1);
                count++;
                while (currMap.get(sub) > wordFreq.get(sub)) {
                    const leftWord = s.slice(left, left + wordLen);
                    currMap.set(leftWord, currMap.get(leftWord) - 1);
                    count--;
                    left += wordLen;
                }
                if (count === wordCount) res.push(left);
            } else {
                currMap.clear();
                count = 0;
                left = j + wordLen;
            }
        }
    }
    return res;
};
